/// <summary>
/// displays HK2 Price per 1000
/// </summary>
/// <param name = "_transDate">date</param>
/// <returns>HK2 Price</returns>
[SysClientCacheDataMethodAttribute(true)]
display NDXHK2PricevAP dispHK2current(TransDate _transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
{
    InventTable lInventTable;
    NDXHK2PricevAP price = 0.0;
    if(!xUserInfo::hasSecuritykeyAccess(privilegeStr(NDXHK2View)))
    {
        return 0;
    }

    lInventTable = InventTable::find(this.ItemId);
    price = this.dispHK1current(_transDate) * lInventTable.ndxGetHK2Factor(_transDate);

    return price;
}

/// <summary>
/// Display MGK/HK2 price (HK1 * HK2Factor * MGKFactor)
/// </summary>
/// <returns>MGK/HK2 Price</returns>
[SysClientCacheDataMethodAttribute(true)]
display NDXHK2MGKPrice dispHK2MGKcurrent()
{
    InventTableModule lInventTableModule = InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent);
    AVAMGKFactors factor = AVAMGKFactors::findByRecId(lInventTableModule.NDXMGKGroupRefRecId);

    //security check  in NDX_showHK2current
    return this.dispHK2current() * (factor.MGKFactor ? factor.MGKFactor : 1);
}

/// <summary>
/// displays HK1 Price per 1000
/// </summary>
/// <param name = "_transDate">date</param>
/// <returns>HK2 Price</returns>
[SysClientCacheDataMethodAttribute(true)]
display NDXHK1PricevAP dispHK1current(TransDate _transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))
{
    InventTableModule lInventTableModule;
    NDXHK1PricevAP price = 0.0;

    if(this.ItemGroupId == 'ZHW')
    {
        lInventTableModule = InventTableModule::find(this.ItemId, ModuleInventPurchSales::Purch);
        price = lInventTableModule.dispHK1PriceDisc();
    }
    else
    {
        lInventTableModule = InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent);
        price = lInventTableModule.dispHK1current();
    }

    return price;
}

/// <summary>
/// Display MGK Price (HK1 * MGKFactor)
/// </summary>
/// <returns>MGK Price</returns>
[SysClientCacheDataMethodAttribute(true)]
display Price dispMGKcurrent()
{
    InventTableModule lInventTableModule = InventTableModule::find(this.ItemId, ModuleInventPurchSales::Invent);
    AVAMGKFactors factor = AVAMGKFactors::findByRecId(lInventTableModule.NDXMGKGroupRefRecId);


    //security check  in NDX_showHK1current
    return this.dispHK1current() * (factor.MGKFactor ? factor.MGKFactor : 1);
}
